def rule_umich_consumer_sentiment_latest_reading(doc: dict) -> list[dict]:
    try:
        import re

        def norm(text: str) -> str:
            return " ".join((text or "").split())

        months = (
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
        )
        month_to_num = {month.lower(): idx + 1 for idx, month in enumerate(months)}
        month_re = re.compile(r"\b(?:%s)\b" % "|".join(months), re.I)
        month_year_re = re.compile(r"\b(?:%s)\s+\d{4}\b" % "|".join(months), re.I)
        month_year_extract_re = re.compile(
            r"\b(?P<month>%s)\s+(?P<year>\d{4})\b" % "|".join(months), re.I
        )
        topic_re = re.compile(
            r"\b(?:University of Michigan consumer sentiment survey|"
            r"Michigan Index of Consumer Sentiment|consumer sentiment survey)\b",
            re.I,
        )
        value_re = re.compile(r"\b\d+(?:\.\d+)?\b")
        verb_re = re.compile(
            r"\b(?:stood at|stood to|fell to|declined to|rose to|reached|was)\b",
            re.I,
        )
        sentence_split_re = re.compile(r"(?<=[.!?])\s+")

        doc_name = (doc.get("doc_name") or "").lower()
        doc_year_match = re.search(r"treasury_bulletin_(\d{4})", doc_name)
        doc_year = int(doc_year_match.group(1)) if doc_year_match else None

        spans = []
        seen = set()

        def add_span(text: str, meta: dict | None = None) -> None:
            cleaned = norm(text)
            if not cleaned:
                return
            key = cleaned.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": cleaned}
            if meta is not None:
                if meta.get("page_no") is not None:
                    span["page_no"] = meta.get("page_no")
                if meta.get("paragraph_no") is not None:
                    span["paragraph_no"] = meta.get("paragraph_no")
                if meta.get("line_no") is not None:
                    span["line_no"] = meta.get("line_no")
            spans.append(span)

        def sentence_score(sentence: str) -> tuple[int, int] | None:
            text = norm(sentence)
            low = text.lower()
            if not text or not value_re.search(low) or not verb_re.search(low):
                return None

            score = 0
            if "stood at" in low:
                score += 6
            if "declined to" in low or "fell to" in low:
                score += 5
            if "rose to" in low or "reached" in low:
                score += 3
            if "latest survey" in low or "most recent" in low:
                score += 2
            if "index has declined" in low or "index then trended" in low:
                score += 1
            if month_re.search(low):
                score += 3
            if "early" in low or "late" in low or "mid" in low:
                score += 1

            latest_date = 0
            for match in month_year_extract_re.finditer(text):
                month_key = match.group("month").lower()
                year = int(match.group("year"))
                latest_date = max(latest_date, year * 12 + month_to_num.get(month_key, 0))
            if latest_date == 0 and doc_year is not None and month_re.search(text):
                for month_match in month_re.finditer(text):
                    month_key = month_match.group(0).lower()
                    latest_date = max(
                        latest_date, doc_year * 12 + month_to_num.get(month_key, 0)
                    )
            if latest_date == 0:
                return None

            return latest_date * 100 + score, len(text)

        paragraph_candidates: list[tuple[int, int, str, dict]] = []
        for paragraph in doc.get("paragraphs") or []:
            raw_text = paragraph.get("text") or ""
            text = norm(raw_text)
            low = text.lower()
            if not text or not topic_re.search(low):
                continue
            if "consumer sentiment" not in low:
                continue

            best: tuple[int, int, str] | None = None
            for sentence in sentence_split_re.split(text):
                scored = sentence_score(sentence)
                if scored is None:
                    continue
                score, length = scored
                candidate = (score, length, norm(sentence))
                if best is None or candidate[0] > best[0] or (
                    candidate[0] == best[0] and candidate[1] < best[1]
                ):
                    best = candidate

            if best is not None:
                paragraph_candidates.append((best[0], best[1], best[2], paragraph))

        if paragraph_candidates:
            paragraph_candidates.sort(key=lambda item: (-item[0], item[1]))
            best = paragraph_candidates[0]
            add_span(best[2], best[3])
            return spans

        lines = doc.get("lines") or []
        for idx, line in enumerate(lines):
            raw_text = line.get("text") or ""
            text = norm(raw_text)
            low = text.lower()
            if "consumer sentiment" not in low:
                continue
            if not topic_re.search(low):
                continue
            start = max(0, idx - 1)
            end = min(len(lines), idx + 3)
            combined = " ".join(
                norm(lines[j].get("text") or "")
                for j in range(start, end)
                if norm(lines[j].get("text") or "")
            )
            if combined:
                add_span(combined, line)
                return spans

        return []
    except Exception:
        return []

import re


_MONTHS = (
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
)
_MONTH_RE = "|".join(_MONTHS)
_HEADER_DATE_RE = re.compile(
    rf"^\s*({_MONTH_RE})\s+(\d{{1,2}})\s*,?\s*(\d{{4}})\s*$",
    re.IGNORECASE,
)
_DOC_NAME_DATE_RE = re.compile(r"_(\d{8})(?:_|$)")


def rule_notice_issuance_date(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def canonicalize(month: str, day: str, year: str) -> str:
            month = month[:1].upper() + month[1:].lower()
            return f"{month} {int(day)}, {year}"

        def header_date_from_items(items: list[dict], limit: int = 35) -> dict | None:
            for item in items[:limit]:
                text = norm(item.get("text") or "")
                if not text:
                    continue
                match = _HEADER_DATE_RE.match(text)
                if match:
                    span = {"text": canonicalize(match.group(1), match.group(2), match.group(3))}
                    for key in ("page_no", "line_no", "paragraph_no"):
                        if key in item:
                            span[key] = item[key]
                    return span
            return None

        # Prefer the explicit header date from the top of the document.
        for source_key in ("lines", "paragraphs"):
            items = [s for s in (doc.get(source_key) or []) if isinstance(s, dict)]
            if not items:
                continue
            found = header_date_from_items(items)
            if found:
                return [found]

        pages = [s for s in (doc.get("pages") or []) if isinstance(s, dict)]
        if pages:
            found = header_date_from_items(pages, limit=2)
            if found:
                return [found]

        # Fallback: derive the issue date from the encoded document name.
        doc_name = doc.get("doc_name") or ""
        match = _DOC_NAME_DATE_RE.search(doc_name)
        if match:
            raw = match.group(1)
            month = int(raw[:2])
            day = int(raw[2:4])
            year = raw[4:]
            if 1 <= month <= 12 and 1 <= day <= 31:
                month_name = _MONTHS[month - 1]
                return [{"text": f"{month_name} {day}, {year}"}]

        return []
    except Exception:
        return []

